// legendas do narrador (06/11, pedido dele: estilo Black Ops 4, no idioma do jogo, liga/desliga em Som)
Object.assign(D.pt, {"vosub_milk": "Pessoal, alguém acabou de virar o LEITE TURBINADO! Olha essas pernas!", "vosub_uav": "Olhos no céu, senhoras e senhores! O RADAR ESPIÃO subiu, ninguém se esconde!", "vosub_talc": "Cof, cof! Lá vem a NUVEM DE TALCO, ninguém enxerga nada!", "vosub_anvil": "Segurem os chapéus! Vai chover BIGORNA!", "vosub_blimp": "Olha pra cima, olha pra cima! O DIRIGÍVEL está no ar!", "vosub_anvline": "Cuidado com a cabeça, pessoal! Uma FILA inteira de bigornas descendo!", "vosub_sentry": "Cheguem mais! A SENTINELA está de guarda e não pisca!", "vosub_rpg": "Minha nossa, minha nossa! Alguém pegou a BAZUCA!", "vosub_plane": "Ouviu esse motor? O BIPLANO está chegando quente!", "vosub_train": "Todos a bordo, pessoal! É o TREM DESGOVERNADO, e ele não para!", "vosub_bomber": "Abaixa e se protege! O DIRIGÍVEL BOMBARDEIRO está soltando a carga!", "vosub_hand": "Senhoras e senhores, o próprio ANIMADOR! Lá vem A MÃO!", "vosub_nuke": "Ah não, ah não, ah NÃO! A TORTA ATÔMICA está no forno! Corram pra salvar a vida!", "vosub_start_a": "Senhoras e senhores, luzes, câmera...", "vosub_start_b": "RUBBER RIOT!", "vosub_lastmin": "Falta um minuto, pessoal! Deem tudo o que têm!", "vosub_win": "QUE ESPETÁCULO! Temos um vencedor, senhoras e senhores!", "vosub_lose": "Ih, que azar, camarada! Mais sorte no próximo rolo!", "vosub_tie": "Cabeça a cabeça, senhoras e senhores! Deu EMPATE!", "vosub_enemystreak": "Ih, pessoal! O outro lado tem coisa feia vindo aí!", "vosub_enemystreak2": "Atenção, pessoal! O time de lá está aprontando!", "vosub_enemystreak3": "Ih! Alguém do outro lado acabou de ter sorte!", "vosub_enemystreak4": "Opa, cuidado onde pisa, camarada! Eles têm uma surpresa pra você!", "vosub_enemystreak5": "Segura essa! O inimigo está chamando a artilharia pesada!", "vosub_enemystreak6": "Abaixa, pessoal, abaixa! Lá vem encrenca do outro lado!", "vosubWho": "Locutor", "s_voSubs": "Legendas do narrador"});
Object.assign(D.en, {"vosub_milk": "Folks, somebody just chugged the TURBO MILK! Look at those legs go!", "vosub_uav": "Eyes in the sky, ladies and gentlemen! The SPY RADAR is up, nobody can hide!", "vosub_talc": "Cough, cough! Here comes the TALC CLOUD, nobody sees a thing!", "vosub_anvil": "Hold onto your hats! It's raining ANVILS!", "vosub_blimp": "Look up, look up! The BLIMP is in the air!", "vosub_anvline": "Watch your heads, folks! A whole LINE of anvils, coming right down!", "vosub_sentry": "Step right up! The SENTRY is on guard, and it doesn't blink!", "vosub_rpg": "Oh boy, oh boy! Somebody grabbed the BAZOOKA!", "vosub_plane": "Hear that engine? The BIPLANE is coming in hot!", "vosub_train": "All aboard, folks! It's the RUNAWAY TRAIN, and it's not stopping!", "vosub_bomber": "Duck and cover! The BOMBER BLIMP is dropping the goods!", "vosub_hand": "Ladies and gentlemen, the ANIMATOR himself! Here comes THE HAND!", "vosub_nuke": "Oh no, oh no, oh NO! The ATOMIC PIE is in the oven! Run for your lives!", "vosub_start_a": "Ladies and gentlemen, lights, camera...", "vosub_start_b": "RUBBER RIOT!", "vosub_lastmin": "One minute left, folks! Give it everything you've got!", "vosub_win": "WHAT A SHOW! We have a winner, ladies and gentlemen!", "vosub_lose": "Ooh, tough break, pal! Better luck in the next reel!", "vosub_tie": "Neck and neck, ladies and gentlemen! It's a TIE!", "vosub_enemystreak": "Uh oh, folks! The other side's got something nasty coming!", "vosub_enemystreak2": "Heads up, folks! The other team's cooking up trouble!", "vosub_enemystreak3": "Uh oh! Somebody on the other side just got lucky!", "vosub_enemystreak4": "Ooh, watch your step, pal! They've got a surprise for ya!", "vosub_enemystreak5": "Hold the phone! The enemy's calling in the big guns!", "vosub_enemystreak6": "Duck, folks, duck! Trouble's coming from the other side!", "vosubWho": "Announcer", "s_voSubs": "Announcer subtitles"});
